create table if not exists project_images(id uuid primary key default gen_random_uuid(),customer_id uuid references estimate_customers(id),property_id uuid references estimate_properties(id),estimate_id uuid references estimates(id),proposal_id uuid references proposals(id),original_storage_path text not null unique,preview_storage_path text,source_type text not null default 'upload',original_filename text not null,mime_type text not null check(mime_type in('image/jpeg','image/png','image/webp')),width integer,height integer,file_size bigint not null check(file_size>0 and file_size<=15728640),category text not null default 'other',title text not null default '',caption text not null default '',customer_comment text not null default '',internal_note text not null default '',attribution text not null default '',created_by text not null,archived boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists project_image_versions(id uuid primary key default gen_random_uuid(),project_image_id uuid not null references project_images(id) on delete restrict,version_number integer not null,derivative_storage_path text,transform jsonb not null,annotations jsonb not null default '[]',legends jsonb not null default '[]',base_updated_at timestamptz,created_by text not null,created_at timestamptz not null default now(),unique(project_image_id,version_number));
create table if not exists proposal_image_instances(id uuid primary key default gen_random_uuid(),proposal_id uuid not null references proposals(id) on delete cascade,project_image_id uuid references project_images(id) on delete restrict,version_id uuid references project_image_versions(id) on delete restrict,section_type text not null check(section_type in('photos','plan')),plan_type text,title text not null default '',caption text not null default '',customer_comment text not null default '',include_in_proposal boolean not null default true,display_order integer not null default 0,layout text not null default 'full',transform jsonb not null,annotations_snapshot jsonb not null default '[]',legends_snapshot jsonb not null default '[]',orientation text not null default 'portrait' check(orientation in('portrait','landscape')),customer_facing boolean not null default true,allow_placeholder boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table proposals add column if not exists image_instances_snapshot jsonb not null default '[]'::jsonb;
create index if not exists project_images_project_idx on project_images(estimate_id,property_id,archived);create index if not exists proposal_image_instances_order_idx on proposal_image_instances(proposal_id,section_type,display_order);
do $$declare t text;begin foreach t in array array['project_images','project_image_versions','proposal_image_instances'] loop execute format('alter table %I enable row level security',t);execute format('create policy "project images service role only" on %I for all using(auth.role()=''service_role'') with check(auth.role()=''service_role'')',t);end loop;end$$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('project-images','project-images',false,15728640,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy "project image objects service role only" on storage.objects for all using(bucket_id='project-images' and auth.role()='service_role') with check(bucket_id='project-images' and auth.role()='service_role');
